from datetime import date, timedelta


class LeaveTracker:
    def __init__(
        self, days_per_year: int = 26, holidays: list[date] | None = None
    ) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays or ())
        self._used: dict[tuple[str, int], int] = {}

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance")

        days_by_year: dict[int, int] = {}
        for offset in range((end - start).days + 1):
            day = start + timedelta(days=offset)
            if day.weekday() < 5 and day not in self.holidays:
                days_by_year[day.year] = days_by_year.get(day.year, 0) + 1

        for year, days in days_by_year.items():
            if days > self.remaining(employee, year):
                raise ValueError(f"Insufficient leave remaining for {year}")

        for year, days in days_by_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + days

        return sum(days_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used.get((employee, year), 0)
